val safe = SourceFile.kotlin("Crate.kt", """
    package movemate

    import workbench.ksp.annotations.Builder

    @Builder
    class Crate {
        constructor(label: String)
    }

    @Builder
    class Safe private constructor(val code: String)
    """)
val run = compileWithKsp(safe, processors = listOf(BuilderProcessorProvider()))
assertThat(run.messages).containsPattern(
    """e: \[ksp] \S*/Crate\.kt:11: SafeBuilder can't call Safe's constructor, because it is private\.""")

