fun check(symbol: KSAnnotated): Boolean {
    if (symbol !is KSClassDeclaration || symbol.classKind != ClassKind.CLASS) {
        logger.error("@Builder needs a class to build, but ${describe(symbol)}. " +
            "Put @Builder on a class with a primary constructor.", symbol)      // the declaration's line
        return false
    }
    val constructor = symbol.primaryConstructor ?: return true      // a missing constructor is another rule
    if (constructor.isPrivate()) {
        logger.error("${symbol.simpleName.asString()}Builder can't call the constructor, because it is private. " +
            "Make it internal or public.", constructor)                       // the constructor's line
        return false
    }
    return true
}

